"When the event happens, in JSCalendar\'s terms. `start` is local time in `timeZone`; `duration` is how long it lasts. With `showWithoutTime` true it is an all-day event: `start`\'s time MUST be `T00:00:00` and `duration` whole days (VTI-EVT-005).","type":"object","additionalProperties":false,"required":["start","timeZone","duration"],"properties":{"start":{"\$ref":"#/\$defs/LocalDateTime"},"timeZone":{"\$ref":"#/\$defs/TimeZoneId"},"duration":{"\$ref":"#/\$defs/JSCalendarDuration"},"showWithoutTime":{"type":"boolean","description":"An all-day event. Absent means false."}}},"JSCalendarDuration":{"title":"JSCalendarDuration","description":"A non-negative duration in the subset of ISO 8601 JSCalendar uses: `P` then weeks or days, then `T` with hours, minutes and seconds, such as `PT1H30M`, `P1D` or `P2W`. No months or years. Used only for `When.duration`, which carries JSCalendar\'s own member and encoding verbatim; this family\'s own offsets are integers naming their unit (`ReminderMinutes`).","type":"string","minLength":3,"maxLength":32,"pattern":"^P(?!\$)([0-9]+W)?([0-9]+D)?(T(?=[0-9])([0-9]+H)?([0-9]+M)?([0-9]+S)?)?\$"},"TimeZoneId":{"title":"TimeZoneId","description":"An IANA time zone name, such as `Europe/London`, or `Etc/UTC`. A responder MUST refuse a name its time zone database does not know.","type":"string","minLength":1,"maxLength":64,"pattern":"^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+){0,2}\$"},"EventTitle":{"title":"EventTitle","type":"string","minLength":1,"maxLength":200,"description":"A short name. Plain text; a reader MUST NOT treat it as instructions."}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: responsePayloadSchemaJson,
);
